ALTER TABLE public.accounts ADD COLUMN smart_sending_enabled boolean NOT NULL DEFAULT true, ADD COLUMN smart_sending_hours integer NOT NULL DEFAULT 24 CHECK (smart_sending_hours BETWEEN 1 AND 8760);
ALTER TABLE public.campaigns ADD COLUMN smart_sending_mode text NOT NULL DEFAULT 'inherit' CHECK (smart_sending_mode IN ('inherit','on','off')), ADD COLUMN smart_sending_hours integer NOT NULL DEFAULT 24 CHECK (smart_sending_hours BETWEEN 1 AND 8760);
CREATE TABLE public.sms_phone_history(account_id uuid NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,phone_e164 text NOT NULL,last_message_id uuid NOT NULL,last_sent_at timestamptz NOT NULL,PRIMARY KEY(account_id,phone_e164));
GRANT ALL ON public.sms_phone_history TO service_role;
ALTER TABLE public.sms_phone_history ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.sms_invalid_destinations(account_id uuid NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,phone_e164 text NOT NULL,reason text NOT NULL,source_message_id uuid,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_id,phone_e164));
GRANT SELECT ON public.sms_invalid_destinations TO authenticated;
GRANT ALL ON public.sms_invalid_destinations TO service_role;
ALTER TABLE public.sms_invalid_destinations ENABLE ROW LEVEL SECURITY;
CREATE POLICY sms_invalid_owner_read ON public.sms_invalid_destinations FOR SELECT TO authenticated USING(public.has_account_access(account_id,'viewer'));
INSERT INTO public.sms_phone_history(account_id,phone_e164,last_message_id,last_sent_at) SELECT DISTINCT ON(c.account_id,m.phone_e164) c.account_id,m.phone_e164,m.id,COALESCE(m.sent_at,m.dispatch_started_at,m.created_at) FROM public.messages m JOIN public.campaigns c ON c.id=m.campaign_id WHERE m.sent_at IS NOT NULL OR (m.status='sending' AND m.charged_at IS NOT NULL) ORDER BY c.account_id,m.phone_e164,COALESCE(m.sent_at,m.dispatch_started_at,m.created_at) DESC;
INSERT INTO public.sms_invalid_destinations(account_id,phone_e164,reason,source_message_id) SELECT DISTINCT ON(c.account_id,m.phone_e164) c.account_id,m.phone_e164,CASE WHEN m.error_code IN ('30006','40001') THEN 'landline' ELSE 'invalid_number' END,m.id FROM public.messages m JOIN public.campaigns c ON c.id=m.campaign_id WHERE m.status IN ('failed','undelivered') AND m.error_code IN ('30005','30006','40001','40012','40310','invalid_phone_number') ORDER BY c.account_id,m.phone_e164,m.created_at DESC;
CREATE FUNCTION public.save_smart_sending_settings(_account uuid,_enabled boolean,_hours integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_account_access(_account,'editor') OR NOT (_account=auth.uid() OR EXISTS(SELECT 1 FROM public.account_members WHERE account_id=_account AND user_id=auth.uid() AND status='active' AND role<>'viewer' AND (role='admin' OR permissions->>'settings'='true'))) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _enabled IS NULL OR _hours IS NULL OR _hours NOT BETWEEN 1 AND 8760 THEN RAISE EXCEPTION 'Choose 1 to 8760 hours'; END IF; UPDATE public.accounts SET smart_sending_enabled=_enabled,smart_sending_hours=_hours WHERE id=_account; END $$;
REVOKE ALL ON FUNCTION public.save_smart_sending_settings(uuid,boolean,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_smart_sending_settings(uuid,boolean,integer) TO authenticated;
CREATE FUNCTION public.sms_send_protection_verdict(_campaign uuid,_message uuid,_phone text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN _phone !~ '^\+[1-9][0-9]{6,14}$' THEN 'invalid_number' WHEN EXISTS(SELECT 1 FROM public.sms_invalid_destinations i WHERE i.account_id=c.account_id AND i.phone_e164=_phone) THEN 'invalid_number' WHEN EXISTS(SELECT 1 FROM public.suppressions s WHERE s.account_id=c.account_id AND s.phone_e164=_phone) THEN 'opted_out' WHEN (CASE c.smart_sending_mode WHEN 'on' THEN true WHEN 'off' THEN false ELSE a.smart_sending_enabled END) AND EXISTS(SELECT 1 FROM public.sms_phone_history h WHERE h.account_id=c.account_id AND h.phone_e164=_phone AND h.last_message_id<>_message AND h.last_sent_at>now()-make_interval(hours=>CASE WHEN c.smart_sending_mode='inherit' THEN a.smart_sending_hours ELSE c.smart_sending_hours END)) THEN 'recently_messaged' ELSE 'ok' END FROM public.campaigns c JOIN public.accounts a ON a.id=c.account_id WHERE c.id=_campaign $$;
REVOKE ALL ON FUNCTION public.sms_send_protection_verdict(uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sms_send_protection_verdict(uuid,uuid,text) TO service_role;
CREATE FUNCTION public.sms_capture_destination_state() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE acct uuid; BEGIN SELECT account_id INTO acct FROM public.campaigns WHERE id=NEW.campaign_id; IF acct IS NULL THEN RETURN NEW; END IF; IF NEW.status IN ('sending','sent','delivered','delivery_unconfirmed') AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN INSERT INTO public.sms_phone_history(account_id,phone_e164,last_message_id,last_sent_at) VALUES(acct,NEW.phone_e164,NEW.id,COALESCE(NEW.sent_at,NEW.dispatch_started_at,now())) ON CONFLICT(account_id,phone_e164) DO UPDATE SET last_message_id=EXCLUDED.last_message_id,last_sent_at=EXCLUDED.last_sent_at WHERE sms_phone_history.last_sent_at<=EXCLUDED.last_sent_at; END IF; IF NEW.status IN ('failed','undelivered') AND NEW.error_code IN ('30005','30006','40001','40012','40310','invalid_phone_number') THEN INSERT INTO public.sms_invalid_destinations(account_id,phone_e164,reason,source_message_id) VALUES(acct,NEW.phone_e164,CASE WHEN NEW.error_code IN ('30006','40001') THEN 'landline' ELSE 'invalid_number' END,NEW.id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.sms_capture_destination_state() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER sms_destination_state AFTER INSERT OR UPDATE OF status,error_code ON public.messages FOR EACH ROW EXECUTE FUNCTION public.sms_capture_destination_state();
DO $$ DECLARE original text; modified text; BEGIN SELECT pg_get_functiondef('public.claim_campaign_messages(uuid,integer)'::regprocedure) INTO original; modified:=replace(original,'IF campaign_account IS NULL THEN RAISE EXCEPTION ''Campaign not found''; END IF;','IF campaign_account IS NULL THEN RAISE EXCEPTION ''Campaign not found''; END IF; PERFORM 1 FROM public.accounts WHERE accounts.id=campaign_account FOR UPDATE;'); modified:=replace(modified,'WHEN p.freq_capped THEN ''frequency_cap''','WHEN public.sms_send_protection_verdict(_campaign_id,p.id,p.phone_e164) <> ''ok'' THEN public.sms_send_protection_verdict(_campaign_id,p.id,p.phone_e164)
        WHEN p.freq_capped THEN ''frequency_cap'''); modified:=replace(modified,'recent.campaign_id <> _campaign_id','recent.campaign_id <> _campaign_id AND recent.sent_at IS NOT NULL AND EXISTS(SELECT 1 FROM public.campaigns rc WHERE rc.id=recent.campaign_id AND rc.account_id=campaign_account)'); modified:=replace(modified,'SET status=''failed'', error_code=c.verdict','SET status=CASE WHEN c.verdict IN (''invalid_number'',''opted_out'',''recently_messaged'') THEN ''skipped'' ELSE ''failed'' END, cost=0, error_code=c.verdict'); modified:=replace(modified,'WHEN c.verdict=''rate_unavailable'' THEN','WHEN c.verdict=''invalid_number'' THEN ''Skipped — invalid number or landline.'' WHEN c.verdict=''opted_out'' THEN ''Skipped — opted out.'' WHEN c.verdict=''recently_messaged'' THEN ''Skipped — recently messaged.'' WHEN c.verdict=''rate_unavailable'' THEN'); IF modified=original OR position('sms_send_protection_verdict(_campaign_id,p.id,p.phone_e164)' IN modified)=0 THEN RAISE EXCEPTION 'Queue definition changed; migration aborted'; END IF; EXECUTE modified; END $$;
DO $$ DECLARE original text; modified text; BEGIN SELECT pg_get_functiondef('public.campaign_report_summary(uuid)'::regprocedure) INTO original; modified:=replace(original,'''total'', (SELECT count(*) FROM m),','''total'', (SELECT count(*) FROM m), ''skipped'', (SELECT count(*) FROM m WHERE status=''skipped''), ''skipped_recently_messaged'', (SELECT count(*) FROM m WHERE status=''skipped'' AND error_code=''recently_messaged''), ''skipped_invalid_number'', (SELECT count(*) FROM m WHERE status=''skipped'' AND error_code=''invalid_number''),'); IF modified=original THEN RAISE EXCEPTION 'Report definition changed'; END IF; EXECUTE modified; END $$;